step1_check_code_field.python_example:
def classify_build_error(build):
    error_detail = build.get('error_detail') or {}
    code = error_detail.get('code')

    if code == 'COMPOSE_CONFIG_ERROR':
        return 'compose_config_error'

    failure_site = build.get('failure_site')
    if failure_site == 'jenkins':
        return 'jenkins_build_error'
    elif failure_site == 'deploy':
        return 'deployment_error'
    elif failure_site == 'validating':
        return 'validation_error'
    else:
        return 'unknown_error'

step2_extract_details.python_example:
def get_error_display_info(build):
    error_detail = build.get('error_detail') or {}

    return {
        'title': build.get('error', 'Build failed'),
        'service': error_detail.get('service'),
        'config_path': error_detail.get('config_path'),
        'remediation': error_detail.get('remediation'),
        'summary': error_detail.get('summary'),
        'failure_site': build.get('failure_site'),
    }

